"use client";

import { useState } from "react";
import GridComandas from "@/components/cocinero/comandas/grid-comandas";
import FiltroComandas from "@/components/cocinero/comandas/filtro-comandas";
import type { EstadoComanda } from "@/types/cocinero";

function MesasDisponiblePage() {
  const [estadoFiltro, setEstadoFiltro] = useState<EstadoComanda>(0);

  return (
    <div className="space-y-3">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Comandas</h2>

        <span className="text-sm text-gray-500 bg-white px-3 py-1 rounded-full shadow-sm border border-gray-100">
          🟢 Actualizado en tiempo real
        </span>
      </div>

      {/* Filtro solo en esta página */}
      <div className="w-full px-4 py-3">
        <FiltroComandas
          opciones={[
            { label: "Pendientes", value: 0 },
            { label: "En cocina", value: 1 },
          ]}
          onChange={setEstadoFiltro}
        />
      </div>

      {/* Mostramos las comandas */}
      <GridComandas estadosIniciales={[estadoFiltro]} />
    </div>
  );
}

export default MesasDisponiblePage;
