"use client";

import { useState } from "react";
import type { Comanda, EstadoComanda } from "@/types/cocinero";
import ComandaCard from "./comanda-card";
import detalle_comandaData from "@/data/detalle_comanda.json";

const comandasIniciales = detalle_comandaData as Comanda[];

type Props = {
  estadosIniciales: EstadoComanda[]; // qué estados mostrar
};

export default function GridComandas({ estadosIniciales }: Props) {
  const [comandas, setComandas] = useState<Comanda[]>(comandasIniciales);

  // Filtra comandas según los estados que recibe la página
  const comandasFiltradas = comandas.filter((c) =>
    estadosIniciales.includes(c.estado),
  );

  const handleAceptar = (id: string) =>
    setComandas((prev) =>
      prev.map((c) => (c.id_comanda === id ? { ...c, estado: 1 } : c)),
    );

  const handleMarcarLista = (id: string) =>
    setComandas((prev) =>
      prev.map((c) => (c.id_comanda === id ? { ...c, estado: 2 } : c)),
    );

  const handleTransferir = (id: string) => alert(`Comanda ${id} transferida`);
  const handleVerDetalle = (id: string) => alert(`Comanda ${id} ver detalle`);

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 auto-rows-fr px-4 pb-4">
      {comandasFiltradas.map((c) => (
        <ComandaCard
          key={c.id_comanda}
          comanda={c}
          onAceptar={() => handleAceptar(c.id_comanda)}
          onMarcarLista={() => handleMarcarLista(c.id_comanda)}
          onTransferir={() => handleTransferir(c.id_comanda)}
          onVerDetalle={() => handleVerDetalle(c.id_comanda)}
        />
      ))}
    </div>
  );
}
